%   returns nu: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    nu = 0;
    d = (r_sun - r_sat);
    a = asils.pc.asin_((695700000 / asils.pc.norm_(d)));
    b = asils.pc.asin_((6378137 / asils.pc.norm_(r_sat)));
    c = asils.pc.acos_(asils.pc.clamp(((-(asils.pc.dot_(r_sat, d))) / (asils.pc.norm_(r_sat) * asils.pc.norm_(d))), (-(1)), 1));
    if (c >= (a + b))
        nu = 1;
    elseif (c < (b - a))
        nu = 0;
    else
        x = ((((c * c) + (a * a)) - (b * b)) / (2 * c));
        y = asils.pc.sqrt_(asils.pc.choose((((a * a) - (x * x)) > 0), ((a * a) - (x * x)), 0));
        ar = ((((a * a) * asils.pc.acos_(asils.pc.clamp((x / a), (-(1)), 1))) + ((b * b) * asils.pc.acos_(asils.pc.clamp(((c - x) / b), (-(1)), 1)))) - (c * y));
        nu = (1 - (ar / ((pi * a) * a)));
    end
end
